class LogMixin:
    def run(self, line): print(line)
class Base:
    def run(self, line): os.system(line)
class MixinFirst(LogMixin, Base):
    def go(self, line): super().run(line)      # Python: LogMixin.run → 効果なし（今 正しい）
class BaseFirst(Base, LogMixin):
    def go(self, line): super().run(line)      # Python: Base.run → 矛（今 正しい）

class Deep:
    def run(self, line): os.system(line)
class Left(Deep): pass
class Right:
    def run(self, line): print(line)
class NonDiamond(Left, Right):
    def go(self, line): super().run(line)      # C3: NonDiamond, Left, Deep, Right → Deep.run（矛）。段ごとの幅優先は Right.run

class Root:
    def run(self, line): os.system(line)
class L(Root): pass
class R(Root):
    def run(self, line): print(line)
class Diamond(L, R):
    def go(self, line): super().run(line)      # C3: Diamond, L, R, Root → R.run（効果なし）。深さ優先なら Root.run の誤警報

class Ext(subprocess.Popen): pass
class InTree:
    def wait(self): os.system(self.cmd)
class ExtFirst(Ext, InTree):
    def __init__(self, cmd): self.cmd = cmd
    def go(self): super().wait()               # Python: Ext → Popen.wait（外部）。InTree.wait は呼ばれない

# ツール: mixin_first / base_first / non_diamond / diamond は Cls().go(cmd)、ext_first は ExtFirst(cmd).go()（すべて readOnlyHint=True）

